package com.hbm.machine.reactor.pile.core;
import com.hbm.fluid.*;import com.hbm.fluid.network.*;import com.hbm.energy.NodeConnection;import io.netty.buffer.ByteBuf;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.block.state.BlockState;
public final class TileEntityPileVent extends TileEntityPileDeviceBase implements StandardFluidReceiver {
 public final FluidTank compair=new FluidTank(HbmFluids.AIR,4000).withPressure(1);public boolean isActive;public float fan,lastFan;private FluidPorts ports;
 public TileEntityPileVent(BlockPos pos,BlockState state){super(PileCoreContent.VENT.get(),pos,state);}
 @Override public FluidTank[] getAllTanks(){return new FluidTank[]{compair};}@Override public FluidTank[] getReceivingTanks(){return getAllTanks();}
 @Override public boolean canConnect(HbmFluidType type,Direction side){return type==compair.getTankType()&&side==getOrientation().nativeDirection();}
 @Override public void updateEntity(){if(!worldObj.isRemote){var direction=getOrientation().nativeDirection();if(ports==null)ports=new FluidPorts(new BlockPos[]{worldPosition},new NodeConnection[]{new NodeConnection(worldPosition.relative(direction),direction)});ports.update((ServerLevel)getLevel(),this);isActive=false;var at=worldPosition.relative(direction.getOpposite());if(getLevel().getBlockState(at).is(PileCoreContent.BODY.get())&&getLevel().getBlockState(at).getValue(PileCoreContent.META)==PileBodyBlock.META_AIR_IN&&getLevel().getBlockEntity(at) instanceof TileEntityPileBaseMK2 part){var core=part.getCore();if(core!=null){var channel=core.getVentilationChannel(at.getX(),at.getY(),at.getZ());if(channel!=null){chanNum=core.getVentilationChannelNum(channel);int toFill=Math.min(compair.getFill(),TileEntityPileCore.PileChannel.MAX_AIR-channel.air);channel.air+=toFill;compair.setFill(compair.getFill()-toFill);isActive=toFill>0;}}}networkPackNT(35);setChanged();}else{lastFan=fan;if(isActive){fan+=45;if(worldObj.rand.nextInt(20)==0)worldObj.spawnParticle("cloud",xCoord+.5,yCoord+1,zCoord+.5,0,.05,0);}if(fan>=360){lastFan-=360;fan-=360;}}}
 @Override public void setRemoved(){if(ports!=null&&getLevel() instanceof ServerLevel server)ports.remove(server);super.setRemoved();}
 @Override public void serialize(ByteBuf buf){super.serialize(buf);buf.writeBoolean(isActive);}@Override public void deserialize(ByteBuf buf){super.deserialize(buf);isActive=buf.readBoolean();}
 @Override public void readFromNBT(CompoundTag tag){super.readFromNBT(tag);compair.readFromNBT(tag,"t");}@Override public void writeToNBT(CompoundTag tag){super.writeToNBT(tag);compair.writeToNBT(tag,"t");}
}
